// persona-card.tsx — one voice in the persona library grid. Numbered, with an
// accent activity dot, trait chips, an italic serif description, and a wpm /
// voice-range footer. Clicking selects it; the active card gets an accent
// outline + filled dot.

import type { CSSProperties } from "react";
import type { PersonaData } from "./types";

export interface PersonaCardProps {
  /** The persona to render. */
  persona: PersonaData;
  /** Zero-based index — rendered as the "01" number badge. */
  index?: number;
  /** Selected state. */
  active?: boolean;
  /** Select handler. */
  onSelect?: (persona: PersonaData) => void;
  /** Accent color for the dot/outline (defaults to the inherited --accent). */
  accent?: string;
}

export function PersonaCard({ persona, index = 0, active = false, onSelect, accent }: PersonaCardProps) {
  const a = accent ?? "var(--accent)";
  const dotStyle: CSSProperties = {
    background: active ? a : `color-mix(in srgb, ${a} 26%, #000)`,
    boxShadow: active ? `0 0 0 4px color-mix(in srgb, ${a} 22%, transparent)` : "none",
  };
  return (
    <div
      className={`pp-persona-card ${active ? "on" : ""}`}
      onClick={() => onSelect?.(persona)}
    >
      <div className="pp-persona-top">
        <div className="pp-persona-num">{String(index + 1).padStart(2, "0")}</div>
        <div
          className="pp-persona-dot"
          style={dotStyle}
          role="img"
          aria-label={active ? "Active persona" : "Inactive persona"}
          title={active ? "Active" : "Inactive"}
        />
      </div>
      <div className="pp-persona-name">{persona.name}</div>
      <div className="pp-persona-accent">{persona.accent}</div>
      <div className="pp-persona-traits">
        {persona.traits.map((t) => (
          <span key={t} className="pp-trait">
            {t}
          </span>
        ))}
      </div>
      <p className="pp-persona-desc">{persona.desc}</p>
      <div className="pp-persona-foot">
        <span className="pp-mono-num">{persona.wpm} wpm</span>
        <span className="pp-mono-num">{persona.voice}</span>
      </div>
    </div>
  );
}

