// PersonaCard — one voice in the persona library grid. Active vs inactive, and
// a small grid showing selection across the roster.
import { useState } from "react";
import { PersonaCard, type PersonaData } from "tsubaki-ds";

const ARIA: PersonaData = {
  id: "aria",
  name: "ARIA",
  accent: "AMER · F",
  traits: ["WARM", "CALM", "MEASURED"],
  voice: "Mezzo · 220–340 Hz",
  desc: "A patient, low-tempo contralto. Tuned for long form support conversations and onboarding.",
  wpm: 142,
};

const ONYX: PersonaData = {
  id: "onyx",
  name: "ONYX",
  accent: "BRIT · M",
  traits: ["DEEP", "DRY", "LACONIC"],
  voice: "Bass · 95–180 Hz",
  desc: "A gravelly broadcast baritone. Reads numbers and proper nouns like he means it.",
  wpm: 128,
};

export function Active() {
  return (
    <div style={{ width: 300, maxWidth: "100%" }}>
      <PersonaCard persona={ARIA} index={0} active />
    </div>
  );
}

export function Inactive() {
  return (
    <div style={{ width: 300, maxWidth: "100%" }}>
      <PersonaCard persona={ONYX} index={1} />
    </div>
  );
}

export function Grid() {
  const [active, setActive] = useState("aria");
  const list = [ARIA, ONYX];
  return (
    <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 0, width: 600, maxWidth: "100%" }}>
      {list.map((p, i) => (
        <PersonaCard key={p.id} persona={p} index={i} active={active === p.id} onSelect={(x) => setActive(x.id)} />
      ))}
    </div>
  );
}

