// glyphs.tsx — brutalist 1px-stroke icon set for the call-control surface.
// Square caps, miter joins, 16-unit viewBox, currentColor stroke so they
// inherit the button's ink. Sized to the call-control button cap height.

export interface GlyphProps {
  /** Pixel size of the square icon. */
  size?: number;
}

export interface MicGlyphProps extends GlyphProps {
  /** Adds the diagonal mute slash. */
  muted?: boolean;
}

/** Upright handset — start a call. */
export function PhoneGlyph({ size = 14 }: GlyphProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 16 16"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.6"
      strokeLinecap="square"
      strokeLinejoin="miter"
      aria-hidden="true"
      style={{ display: "block" }}
    >
      <path d="M3.2 2.4h3.2l1.2 3.2-1.8 1.2a8 8 0 0 0 3.4 3.4l1.2-1.8 3.2 1.2v3.2c0 .55-.45 1-1 1A11.6 11.6 0 0 1 2.2 3.4c0-.55.45-1 1-1z" />
    </svg>
  );
}

/** Hang up — clean cross. Universal "end". */
export function PhoneHangGlyph({ size = 14 }: GlyphProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 16 16"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="square"
      aria-hidden="true"
      style={{ display: "block" }}
    >
      <line x1="3" y1="3" x2="13" y2="13" />
      <line x1="13" y1="3" x2="3" y2="13" />
    </svg>
  );
}

/** Mic body + stand. Mute state adds a diagonal slash. */
export function MicGlyph({ size = 14, muted = false }: MicGlyphProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 16 16"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.4"
      strokeLinecap="square"
      strokeLinejoin="miter"
      aria-hidden="true"
      style={{ display: "block" }}
    >
      <rect x="6" y="2" width="4" height="8" />
      <path d="M3.5 8.5a4.5 4.5 0 0 0 9 0" />
      <line x1="8" y1="13" x2="8" y2="15" />
      <line x1="5.5" y1="15" x2="10.5" y2="15" />
      {muted && <line x1="2.5" y1="2.5" x2="13.5" y2="13.5" strokeWidth="1.8" />}
    </svg>
  );
}

/** Open-end wrench at 45° — the tools affordance. */
export function WrenchGlyph({ size = 14 }: GlyphProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 16 16"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.4"
      strokeLinecap="square"
      strokeLinejoin="miter"
      aria-hidden="true"
      style={{ display: "block" }}
    >
      <line x1="3" y1="13" x2="9" y2="7" />
      <path d="M9.5 6.5 L12 4 L13.2 5.2 L13.2 7.2 L11.2 7.2 L10 8.4 Z" />
    </svg>
  );
}

/** Paper scroll — top + bottom rolled edges, text lines between. Transcript toggle. */
export function ScrollGlyph({ size = 14 }: GlyphProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 16 16"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.4"
      strokeLinecap="square"
      strokeLinejoin="miter"
      aria-hidden="true"
      style={{ display: "block" }}
    >
      <rect x="2.5" y="2" width="11" height="2" />
      <line x1="3.5" y1="4" x2="3.5" y2="12" />
      <line x1="12.5" y1="4" x2="12.5" y2="12" />
      <line x1="5" y1="6.5" x2="11" y2="6.5" />
      <line x1="5" y1="9" x2="11" y2="9" />
      <rect x="2.5" y="12" width="11" height="2" />
    </svg>
  );
}

/** Arrow into an end-bar — "send / commit my turn" (half-duplex cascade STT). */
export function SendGlyph({ size = 14 }: GlyphProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 16 16"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.6"
      strokeLinecap="square"
      strokeLinejoin="miter"
      aria-hidden="true"
      style={{ display: "block" }}
    >
      <line x1="2" y1="8" x2="10" y2="8" />
      <path d="M7 5 L10 8 L7 11" />
      <line x1="13" y1="3.5" x2="13" y2="12.5" />
    </svg>
  );
}

/** Open palm — "stop / hold on, let me talk". Interrupt the agent. */
export function InterruptGlyph({ size = 14 }: GlyphProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 16 16"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.4"
      strokeLinecap="square"
      strokeLinejoin="miter"
      aria-hidden="true"
      style={{ display: "block" }}
    >
      <path d="M5 8V3.5a1 1 0 0 1 2 0V7" />
      <path d="M7 7V2.5a1 1 0 0 1 2 0V7" />
      <path d="M9 7V3a1 1 0 0 1 2 0v5" />
      <path d="M11 5.5a1 1 0 0 1 2 0V10a4 4 0 0 1-4 4H8a3 3 0 0 1-2.6-1.5L3 8.5a1 1 0 0 1 1.7-1L6 9" />
    </svg>
  );
}

/** Thinner mic glyph tuned to the MicSelector control's cap height. */
export function MicLineGlyph({ size = 13, muted = false }: MicGlyphProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 16 16"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.3"
      strokeLinecap="square"
      aria-hidden="true"
      style={{ display: "block", flexShrink: 0 }}
    >
      <rect x="6" y="2" width="4" height="8" />
      <path d="M3.5 8.5a4.5 4.5 0 0 0 9 0" />
      <line x1="8" y1="13" x2="8" y2="15" />
      <line x1="5.5" y1="15" x2="10.5" y2="15" />
      {muted && <line x1="2.5" y1="2.5" x2="13.5" y2="13.5" strokeWidth="1.6" />}
    </svg>
  );
}

/** Up/down double chevron — opens a picker popover. */
export function ChevGlyph({ size = 10 }: GlyphProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 10 10"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.2"
      strokeLinecap="square"
      aria-hidden="true"
      style={{ display: "block", flexShrink: 0 }}
    >
      <path d="M2 3.5L5 1 8 3.5M2 6.5L5 9 8 6.5" />
    </svg>
  );
}

